#include <array>
#include <vector>
#include <cstddef>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(image.size());

    #pragma omp parallel
    {
        std::array<size_t, 256> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const int value = image[static_cast<std::size_t>(i)];
            if (value >= 0 && value < 256) {
                ++local_bins[static_cast<std::size_t>(value)];
            }
        }

        for (std::size_t b = 0; b < 256; ++b) {
            #pragma omp atomic
            bins[b] += local_bins[b];
        }
    }
}
